<?php /* Time regularisation fields of a salary revision: $c (revision or null), $id (unique suffix for field ids), optional $stack (one column). Mode default = company setting, custom = minutes below, off. */
use Modules\Payroll\Services\PayrollService;
$g = $c['grace_minutes'] ?? null; $mode = old('grace_mode', $g === null || $g === '' ? 'default' : ((int) $g === 0 ? 'off' : 'custom')); $def = PayrollService::graceDefault(); ?>
<div class="<?= empty($stack) ? 'form-grid' : 'stack' ?>">
  <div class="field"><label for="grace-mode-<?= e($id) ?>">Time regularisation</label><select id="grace-mode-<?= e($id) ?>" name="grace_mode"><option value="default"<?= selected('default', $mode) ?>>Company setting (<?= $def ? $def.' min' : 'off' ?>)</option><option value="custom"<?= selected('custom', $mode) ?>>Custom for this employee</option><option value="off"<?= selected('off', $mode) ?>>Off for this employee</option></select><?= error_for('grace_mode') ?></div>
  <div class="field"><label for="grace-min-<?= e($id) ?>">Custom minutes</label><div class="pay-unit"><input id="grace-min-<?= e($id) ?>" type="number" name="grace_minutes" min="1" max="1440" step="1" value="<?= e(old('grace_minutes', $mode === 'custom' ? (string) (int) $g : '')) ?>" placeholder="<?= (int) ($def ?: 90) ?>"><span>min</span></div><div class="hint">Used when Custom is selected.</div><?= error_for('grace_minutes') ?></div>
</div>
